/** Per-reaction shuffle bags — use every variant before reshuffling. */
const variantDecks = new Map<string, number[]>();

function shuffleIndices(len: number): number[] {
  const arr = Array.from({ length: len }, (_, i) => i);
  for (let i = arr.length - 1; i > 0; i -= 1) {
    const j = Math.floor(Math.random() * (i + 1));
    const tmp = arr[i]!;
    arr[i] = arr[j]!;
    arr[j] = tmp;
  }
  return arr;
}

function pickVariant(
  variants: string[],
  fallback: string,
  deckKey = 'default',
): string {
  if (!variants.length) return fallback;
  let deck = variantDecks.get(deckKey);
  if (!deck || deck.length === 0) {
    deck = shuffleIndices(variants.length);
    variantDecks.set(deckKey, deck);
  }
  const index = deck.pop() ?? 0;
  return variants[index] ?? fallback;
}

export function getReactionDefinition(
  id: ReactionType | string | number,
): ReactionDefinition | undefined {
  return PREDEFINED_REACTIONS.find((r) => String(r.id) === String(id));
}

export function getReactionMessage(
  reactionType: ReactionType | string | number,
): string {
  const def = getReactionDefinition(reactionType);
  if (!def) return '';
  return pickVariant(
    def.defaultMessages,
    def.defaultMessage,
    `msg:${String(reactionType)}`,
  );
}

export function buildNotificationBody(
  senderName: string,
  reactionType: ReactionType | string | number,
  fallback?: { emoji: string; title: string; message?: string },
): string {
  const name = senderName.trim() || 'Someone';
  const def = getReactionDefinition(reactionType);

  if (def) {
    if (def.isMeta && fallback?.message?.trim()) {
      return `${name}: ${fallback.message.trim()}`;
    }
    const template = pickVariant(
      def.notificationTemplates,
      def.notificationTemplate,
      `notif:${String(reactionType)}`,
    );
    return template.replace('{name}', name);
  }

  if (fallback?.message?.trim()) return `${name}: ${fallback.message.trim()}`;
  if (fallback) return `${name} sent ${fallback.emoji} ${fallback.title}`;
  return `${name} sent you a feeling`;
}

export function parseReactionType(value: unknown): ReactionType | undefined {
  if (value === 'custom' || value === 'custom_text') return value;
  if (typeof value === 'number' && value >= 1 && value <= 100) {
    return value as ReactionType;
  }
  if (typeof value === 'string' && /^\d+$/.test(value)) {
    const n = Number(value);
    if (n >= 1 && n <= 100) return n as ReactionType;
  }
  return undefined;
}

export function defaultEnabledReactions(): Record<string, boolean> {
  const map: Record<string, boolean> = {};
  for (let i = 1; i <= 100; i += 1) {
    map[String(i)] = true;
  }
  map.custom_text = true;
  map.custom = true;
  return map;
}
